def bubbleSort(L):
    n = len(L)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if L[j] > L[j + 1]:
                L[j], L[j + 1] = L[j + 1], L[j]
        print("Pass", i + 1, ":", L)

data = [8, 3, 6, 1, 5]
bubbleSort(data)

def linearSearch(L, key):
    for i in range(len(L)):
        print("Checking position", i, ":", L[i])
        if L[i] == key:
            return i
    return -1

data = [12, 5, 9, 17, 3]
pos = linearSearch(data, 17)
print("Found at position", pos)

def binarySearch(L, key):
    low, high = 0, len(L) - 1
    while low <= high:
        mid = (low + high) // 2
        print("low", low, "high", high, "mid", mid, ":", L[mid])
        if L[mid] == key:
            return mid
        elif L[mid] < key:
            low = mid + 1
        else:
            high = mid - 1
    return -1

data = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]
print("Found at", binarySearch(data, 23))
